[295552341]="Więc to jest to, po co przyszliście? Aby spróbować przywłaszczyć sobie to, co jest powodem istnienia Świtu i upadku Krucjaty? Otwieracie stare rany swoimi słowami, Dowódco!",
[295624269]="Co... co się tu dzieje?",
[295938029]="Moje wierzchowce udostępniam tylko tym, którzy są uważani za przyjaznych Orgrimmarowi i rasie Orków. Idź i udowodnij nam swoją wartość, a udostępnię ci moje potężne wilki do inspekcji.",
[296058902]="Byłem tutaj dość długo. Jestem pewien, że się spotkamy ponownie. Powodzenia!",
[296150360]="Zastanawiam się, czy twoja lalka potrafi pływać!",
[297615879]="O nie...",
[298170622]="Wyobraźnia to jedyna granica, przyjacielu. Jeśli potrafisz to wykuć, możesz to spakować, wysłać do detalistów na całym świecie. Oczywiście, potem musisz zajmować się marketingiem. Wiesz co? Zostańmy przy kuciu na razie, dobrze?",
[299341440]="%s wygląda na ulżonego.",
[299903447]="To zła odpowiedź. Idź sobie.",
[300187483]="Czy to prawda, że paladinowie tutaj się szkolą?",
[301992973]="Tym razem naprawdę przeszła pani samą siebie, pani Chambers. Ani śladu pleśni!",
[302405566]="Gimlok, nie bruj sobie ubrania!",
[302746555]="I wielką część honoru będziesz miał, jestem pewny. Porozmawiaj z Martinem Lindseym przy Zbiornikach Wizji. To jaskinia zlokalizowana po bokach Spirit Rise.",
[304431121]="Moje nogi boleją...",
[304672764]="Staraj się być przydatny, . WYPUŚĆ MNIE STĄD! Wysoki Inkwizytor ma klucz.",
[305606419]="Cześć, . Interesuje cię przetrwanie na wolności? Zdobywanie pożywienia ze zwierząt i roślin!  Możesz nauczyć się czegoś ode mnie, oczywiście, jeśli cię to interesuje.",
[305833236]="Z przyjemnością...",
[307496488]="Ludzie są zwykle wrażliwi po lewej stronie między czwartym a piątym żebrem. Ćwiczmy ataki w to miejsce w ten sposób...",
[307968038]="Czasy takie napełniają mnie sentymentem...",
[309834794]="Horda zdobyła Irondeep Mine!",
[310183748]="Skaczące trędowate gnomy! Byłem tam uwięziony przez miesiące. Dziękuję, gang.",
[311034595]="%s wytwarza swoją truciznę...",
[312151567]="Precz, plugawe stworzenia! Wracajcie do Pustki, z której ukształtował was wasz pan!",
[313090275]="Kryształ Ash'ari został przewrócony! Przywróć zigurat, zanim Nekropolia stanie się bezbronna!",
[313952962]="To specjalistyczny sprzęt! Nie obchodź się z nim beztrosko i oczywiście nie próbuj go obsługiwać, jeśli za dużo piłeś tego niebezpiecznego rumu, o którym słyszę, że go lubisz.BZresztą mówiąc... nie masz przypadkiem trochę tej paskudnej rzeczy, prawda?",
[314439367]="NIE POZWÓL TEMU POSĄGOWI BYĆ MOJĄ JEDYNĄ TOWARZYSZKĄ. WYJDŹ I BAWMY SIĘ!",
[315052656]="Jestem doskonale obeznany z ponad 4 językami.",
[315435599]="Opowiedz mi jeszcze o kopalnach...",
[316767547]="Światło płonie jasno w tobie, Davil. Z przyjemnością je zgaszę!",
[319032898]="Tak jak przeznaczono przed wiekami w Karazhan, potworze - przychodzę i niosę ze sobą sprawiedliwość.",
[319188731]="Moja śmierć mało znaczy... Młot i tak spadnie!",
[319587568]="To nie powinno trwać długo...",
[319636970]="Będziecie mieć wiele wzlotów i upadków, ale jeśli się nie poddacie, przejażdżka będzie tego warta.",
[320097066]="W tamtych latach, gdy niezgoda ogarnęła ziemię, a Legion i Plaga plądrowali nasze domy i zabijali nasze rodziny, te owady mieszkały pod nami. Pod naszymi domami - czekały.",
[320631224]="Jeśli chcesz zostać moim uczniem, będziesz musiał wykonać dla mnie zadanie. Udowodnij swoją godność, a ja mogę nawet rozważyć nagrodę dla ciebie.",
[321616066]="Tak, panie!",
[321980277]="Trudy żywych nigdy nie przestają zdumiewać. Wasza liczba jest ograniczona, a z każdą bitwą maleje. Nie dożyjecie końca!",
[322178594]="Myślę, że odpoczę chwilę i odetchnę, zanim wrócę do Ratchet. Dziękuję za całą pomoc!",
[322484556]="Cmentarz Lodowatej Krwi jest atakowany! Jeśli nikt nie powstrzyma ataku, Horda go przejmie!",
[323561746]="Warg, czy jesteś gotowy do jedzenia? Zaraz zaczynam.",
[324453374]="Na Sentinel Hill spokój, Lord Stoutmantle. Zgłoszono jednak duże ruchy Defiasów w Moonbrook.",
[325227844]="Dobra robota. Zdobyłeś najwyższe wyróżnienie w krawiectwie. Idź i czyń straszne rzeczy dzięki tej wiedzy!",
[325331666]="Proszę...",
[325642467]="Najeźdźcy! Młot spadnie na was.",
[325792766]="Proszę, pomóż mi przejść przez ten przeklęty las, .",
