[327591582]="Obawiam się, że nie,  . Teraz czuj wstyd, jaki na siebie ściągnąłeś.",
[327655363]="Zadbaj o siebie! Zmiatam z tego miejsca!",
[328578704]="Oddział.. STÓJ!  ... W SZEREG!",
[328761977]="Hej chłopaki, spróbujmy z drugiej strony.",
