[329350340]="Twój świat dozna okrutnego końca. Koszmar idzie po ciebie!",
[329533313]="Będę miał wielką przyjemność, zabierając życie tej nieszczęsnej istoty! Nie jest jeszcze za późno, ona nie musi cierpieć na próżno. Odwróć się, a jej śmierć będzie miłosierna!",
