[331081434]="Idź szybko, . Mój los jest w twoich rękach.",
[331465025]="Ty, żołnierzu, natychmiast wróć do Kargath!",
[331659146]="Ja się bać! Ja teraz uciekać!",
[331743122]="Lekkomyślni śmiertelnicy! Nikt nie może wyzwać Synów Żywego Płomienia!",
[332211189]="Teraz to mnie wkurzyło!",
[332488422]="Zawsze to ty sprawiałeś w rodzinie kłopoty, Noggle. Zawsze!",
[332800360]="Przywitaj mojego małego przyjaciela.",
[334049144]="TRZYMAĆ LINIĘ! NIC NIE PRZEPUSZCZAĆ!",
[334380588]="Próba dowiedzenia się czegoś więcej na temat mojej sytuacji była prawie niemożliwa. Przemytnik, który nas wynajął, zniknął, a Anthion Harmon, lider naszej grupy najemników, nie żyje.",
[334896295]="Wreszcie jestem wolny! Wkrótce wrócę do domu, moja droga!",
[334975902]="Jak śmiesz bezcześcić to starożytne miejsce!",
