[344946694]="%s rozdziera się!",
[345137615]="Tower Point East chroni przejście między Field of Strife a terytoriami Hordy na południu.BJest kontrolowany przez Przymierze.Wschodnia Wieża Szronowego Wilku chroni bramę między Wioską Szronowego Wilku a Warownią Szronowego Wilku.BJest kontrolowana przez Przymierze.",
[345328517]="Zostań blisko...",
