[349864872]="Myślałem, że coś słyszę.",
[350539394]="%s bada krąg kamieni, szukając oznak uszkodzenia.",
[350707486]="Ragnaros wszystko widzi, śmiertelniku.",
[350886843]="Teraz, gdy masz okazję zbadać chochlika, przejdźmy do następnego sługusa, którego będziesz mógł przywołać - Chodzącego Próżnią.",
