[351795847]="My myślimy, że potrzebujesz pomocy.",
[352168756]="Dziękuję za ser!",
[352689712]="Gnomy mogą być trudne do trafienia ze względu na ich rozmiar. Jednak mają obsesję na punkcie tańczenia i machania biodrami. Kiedy to robią, atakuj je w ten sposób...",
