[363958589]="Oszczędzałem to miejsce na coś wyjątkowego. Nie sądzę, aby mogło być coś bardziej wyjątkowego niż to.",
[364573151]="Nie ma dla was zwycięstwa tutaj! Wszystkie zdobyte terytoria zostaną pochłonięte przez armię Plagi w odpowiednim czasie!",
[365103275]="Czy to był twój los, Windsor? Jeśli śmierć była tym, czego szukałeś, proroctwo się spełniło. Niech twoja świadomość zgnije w Skręcającym Nether. Dokończcie resztę tych irytujących owadów, dzieci. Bolvar, byłeś przyjemną marionetką.",
