[382825842]="Znajdziesz Fineous Darkvire poza Pierścieniem Prawa, w Hali Rzemiosła. Zabij tego nędznika i odzyskaj Ironfel.BZanieś Ironfel do Świątyni Thaurissan i umieść młot w jego właściwym miejscu: W rękach posągu wzniesionego na moją cześć.BGdy to będzie zrobione, schowek, w którym przechowywałem główny klucz, się otworzy. Ważniejsze jednak jest to, że Ironfel na zawsze pozostanie w moich rękach. Jeśli podejmą próbę usunięcia młota, zarówno posąg, jak i młot roztrzaskają się na zawsze.",
[383437141]="Co to było?! Trey? TREY!?!",
