[1475507025]="Nie bój się; jesteśmy tutaj, aby ci pomóc. Jesteśmy wdzięczni za obronę, którą nam udzieliłeś w naszym dawnym domu, i jako podziękowanie przyszliśmy, aby pomóc ci szybko wrócić do Ziem Plagi, jeśli będzie ci potrzebne. Mój towarzysz może wyjaśnić proces dalej; znajdziesz go tam, gdzie energie arkaniczne są najsilniejsze w tym mieście.",
[1475877452]="Tresa Farmountain przetrwała już wiele złej pogody, ale dzięki swojej wiedzy o umiejętnościach Przetrwania wychodzi z tego z wysoką głową. Przebywa w Military Ward na południe od bram Ironforge, jeśli chcesz z nią porozmawiać.",
