[1550968521]="Cenarius walczy u mojego boku. Illidan siedzi na szczycie swojego tronu na Outlandzie, pogrążony w ponurych myślach. Obawiam się, że porażka z Arthasem okazała się dla niego punktem załamania. Szaleństwo go ogarnęło, Remulosie. Tysiące razy dziennie odtwarza w myślach tamte wydarzenia, ale w jego umyśle to on jest zwycięzcą, a Arthas jest całkowicie pokonany. Zaszedł zbyt daleko, stary przyjacielu. Obawiam się, że wkrótce nadejdzie czas, gdy nasze więzi zostaną wystawione na próbę i nie będzie tak jak przy Studni w Zin-Azshari.",
