[1556267868]="Za to zapłacisz!",
[1556351552]="Jeszcze raz dziękuję. Ruszę teraz w stronę drogi. Gdy tylko będziesz $g mógł : mogła;, znajdź Terenthisa i daj mu znać, że uciekliśmy.",
