[1714580517]="Witaj, ! Nasze zasoby są wysokie i jesteśmy gotowi rozpocząć szturm naziemny przez Pole Walki. Może gdyby twoja sława była większa, zaufałbym ci i powierzył ci dostarczenie rozkazów szturmu.BWięc ruszaj tam i walcz z Przymierzem! Pokaż mi, że jesteś zaufanym i zdolnym członkiem Hordy!",
