[1716632787]="Ustępcie! Ustępcie!",
[1717581425]="%s kontratakuje z zemstą.",
[1717594704]="Kto śmie atakować Posterunek Skrzydła Srebra?!?",
[1717823790]="Czas aby Karawana Gizleton wyruszała w drogę! Wrócimy niedługo, ale jeśli nie możesz czekać, idź na północ do Chatki Kormeka. Otwieramy sklep za około godzinę.",
[1718111328]="Porozmawiaj ze mną, jeśli wybierasz się do Gnomereganu, !",
