[1720084870]="%s dokładnie bada Kamień Plagi.",
[1721139265]="Nie zarabiam wystarczająco dużo za to!",
[1721470832]="Co to? Orkowie już się zbliżają?",
[1721993231]="Witaj, żołnierzu. Wywiad donosi, że trolle Winterax na zachodzie wzięły do niewoli mistrza inżyniera goblinów. Może powinieneś to zbadać?",
