[1726017406]="Pomocy! Goni mnie rój pszczół!",
[1727224170]="%s znika.",
[1728223698]="Cześć Corbett! Proszę bardzo! Mam nadzieję, że interesy w twoim sklepie z odzieżą idą dobrze...?",
[1728567926]="Czekaj... słyszałeś to? Coś podchodzi od zachodu!",
[1728580893]="Przyszła pora, bracia. Nie możemy pozwolić wrogom posuwać się przez Przesmyk Mroznego Sztyletu. Niektórzy z nas na pewno padną, ale czy któryś z was unikałby tego obowiązku? Tego honoru? Naprzód! Dla Hordy!",
