[1730715569]="Niech będzie wiadomo, że - Przymierze - zyskało wieczną cześć Ironforge i całego Przymierza. $GOn : Ona; $Gzaangażował : zaangażowała; się w wielką dyplomację z Timbermaw Hold i $Gwykonał : wykonała; bohaterskie czyny w ich imieniu. $GOn : Ona; $Gposzedł : poszła; ponad obowiązek. Trzy hurra dla - prawdziwego bohatera Przymierza!",
