[1784373185]="Kapitan Ballinda Stonehearth wkrótce przybyje do swojej fortecy. Wkrótce dojdzie do nowej bitwy!",
[1786389459]="Ah tak, wylinka - nie zgub jej. W Burning Steppes są moi pobratymcy, którzy wytwarzają przedmioty, jakie może wzmocnić tylko wylinka czarnego Smoczego Lotu.",
