[1790861661]="%s rzuca ogromny cień na cały Silithus.",
[1791282926]="%s uderza się w pierś, wołając o pomoc!",
[1794338363]="Ah, warstwa ochronna prawie zniknęła. Czy słyszycie to, bohaterowie? To... To jest dźwięk nieuchronności. Waszych nadziei i snów miażdżonych ciężarem mojego bytu.",
[1795677617]="Liladris czeka na mnie w Maestra's Post, więc powinniśmy się spieszyć, .",
[1795696845]="Grark Lorkrub, oskarżono cię i uznano za winnego zdrady wobec Hordy. To, co powiesz w swojej obronie, nie ma znaczenia. Wysoki Kacie Nuzrak, wystąp.",
[1797860539]=" zdobył flagę Hordy!",
[1797865578]="Totem jest gotów, .",
[1798705996]="Interesy muszą dobrze iść na bazarze. Natychmiast dostarczę mu zaopatrzenie!",
[1799147203]="Głupcy! Walczcie, jeśli taka jest wasza wola! Z każdą bitwą wasze szeregi się kurczą, a szeregi nieumarłych rosną!",
[1799194428]="Podczas gdy Greta skupia swoją energię na odzyskaniu Jaedenaru i tych, których uważa za głównie odpowiedzialnych za korupcję tutaj w Felwood. Spędzam swój czas badając skutki, jakie korupcja wywarła na ziemi.BJak to wpłynęło na stworzenia ziemi? Co trzeba zrobić, aby zakończyć ból ich cierpienia?BNiestety, korupcja sięga tak głęboko, że wieczny sen zbyt często jest odpowiedzią.",
