[1806880338]="Jeśli pozwolicie, muszę się oddalić. Dobrego dnia, panie.",
[1807914087]="Tak, proszę pani, interes kwitnie!",
[1807975843]="Athrikus przybył do nas. Powiedział, że może nas uratować. Rzucił zaklęcie na nas, aby nas chronić przed szkodą.",
