[2311034005]="Ah... bohaterowie. Jesteście uparci, nieprawdaż? Wasz sprzymierzeniec próbował mierzyć się z moją mocą - i zapłacił za to wysoką cenę. Teraz będzie mi służył... zabijając was.",
