[2316869612]="Stary Bóg stworzyłby z silithidów awatary na swój obraz. Te awatary miały być znane jako Qiraji. Świadomi i obdarzeni celem, Qiraji nadaliby imię swojemu twórcy: narodził się C'Thun... Przez wiele tysięcy lat Qiraji gorączkowo pracowali nad zbudowaniem siły zdolnej zniszczyć świat, który zdradziłby ich boga. Wielkie miasto-twierdza Ahn'Qiraj zostało wzniesione, aby pomieścić ich rosnące armie i przygotować się na przyjście C'Thuna.",
[2317112859]="Zwycięstwo! Za Agamaggan!",
[2317775955]="To twoje przywództwo zmanipulowało pogrążone w żałobie dziecko, aby spróbowało odzyskać miecz. Dziecko, które wyrosło na mężczyznę z niczym innym w sercu poza zemstą i nienawiścią! A po co? Nie jesteś teraz bliżej tego miecza, niż byłeś pięć lat temu.",
