[2458315039]="Mam nadzieję, że pozostaną żywi wystarczająco długo, abym mógł się im... przedstawić.",
[2458502898]="Powodzenia z Arugalem. Muszę się spieszyć z powrotem do Hadreca.",
[2459081646]="Wszystkie zadania dotyczące wysiłku wojennego Hordy są ukończone, młody . Teraz musimy tylko czekać, aż Przymierze również zakończy swoje i wszystko będzie gotowe do Wojny o Ahn'Qiraj. Z wyjątkiem, być może, zebrania i ponownego połączenia fragmentów Berła Przesuwających się Piasków?",
[2460196922]="Niech ta ciemność wam przypomni: cień Plagi rozprzestrzenia się wszędzie! Nie ma ucieczki!",
[2460614477]="Dusza mi się raduje na widok murów Stormwind, które stoją mocne i wysokie. Jeśli chcesz udać się do Stratholme, obawiam się, że w tej chwili nie mogę ci pomóc. Wieże w pobliżu płonącego miasta wciąż są sporne, a przez to moje moce są zbyt słabe, aby ci pomóc. Wróć do mnie, gdy tam zwyciężysz.",
[2461106973]="Jesteśmy już na miejscu?",
