[2472013903]="Moje maszyny są przyszłością! Zniszczą was wszystkich!",
[2472631820]="Nie ma żadnej łyżki.",
[2473114991]="Tatuś!",
[2473162833]="Nie okazujcie tym dzikusom litości, żołnierze! Oni wam jej nie okażą!",
[2473505842]="Wielu by ci powiedziało, że Biegacz na długich nogach to śmieszny zwierzak. Ale jego inteligencja i lojalność sprawiają, że w wielu sytuacjach trudno mu dorównać. Jeśli interesuje cię ta rasa, mogę nauczyć ciebie i twojego zwierzaka kilku sztuczek, których nauczyłem się przez lata.",
[2473716312]="Zapłacisz za to...",
