[2512603197]="GIŃCIE, DEMONICZNE PSY!",
[2512765600]="Remulos, zobacz jak łatwo padają przede mną? Możesz to zatrzymać, głupcze. Oddaj mi druida, a wszystko będzie skończone...",
[2513009962]="%s ryczy do Terenthisa, aby przyciągnąć jego uwagę.",
[2514248667]="%s wręcza świecące okulary Doktorowi Draxlegauge.",
[2514426486]="Osłoń mnie, uciekam!",
