[2523445549]="Dość! Znudziły mnie te rozpraszania!",
[2524513457]="%s wpada w szaleństwo!",
[2525222441]="To niemożliwe! Jestem tu panem! Wy, śmiertelnicy, jesteście niczym dla mojego rodzaju! Czy mnie słyszycie? Niczym!",
[2525278499]="Pierwotni Bogowie? Niemożliwe!",
[2525546853]="Potrzebujemy lepszego wsparcia ze Stormwind. Nasze domy padają ofiarą nieumarłych.",
[2526104964]="Cóż, to powinno wystarczyć. Chodź teraz, z powrotem do sklepu, aby dokończyć naszą sprawę!",
[2527249179]="Hej, co się tam dzieje? Panie, wszystko w porządku? Panie??",
[2527716357]="Twoje zadanie jest ukończone. Przygotuj się na swoją zagładę.",
[2528069240]="Jeśli Therzok cię posłał, powiedz mu nie, nie wrócę do pracy dla niego, bez względu na to, ile razy prosi.",
[2528197999]="Jesteś tu jeszcze, Reethe?",
[2528246172]="%s woła do swojego partnera!",
[2528355340]="Rozkazuję wam zesłać deszcz ognia na tych najeźdźców!",
[2529627908]="Ah, Szeregowiec Hendel. Przyjemność poznać jednego z ludzi, którzy zdradziliby swoje królestwo dla dumy.",
[2530155369]="Szybko i pewnie. Przetnij ścięgno tu, przetnij tętnicę tam. Mogę ci pokazać, jak każdy nóż zmienić w doskonałą machinę zabijania.",
[2531740636]="Dziękuję ci. I powodzenia!",
[2531816975]="Mam tutaj rozkazy do ataku na siły Przymierza na środkowych polach. Potrzebuję kogoś, aby dostarczył je przywódcy ataku.",
[2533299605]="Niewierni!",
[2533405903]="Ta zamarznięta kraina wystarczy na początek. Przychodźcie do mnie, śmiertelnicy - a ja dam wam szybką i bolesną śmierć.",
[2533521474]="Weź to, bestio!",
[2534662365]="Niech krew przelewana tu dzisiaj będzie lekcją dla wszystkich, którzy ośmielą się wkraczać na tereny Klanu Czarnej Skały!",
[2534826365]="%s zerka na !",
[2535074048]="Pewnego dnia utopię go w tej niebieskiej szacie. I wszystkie jego miotły też.",
[2535278553]="Oczywiście, że gadam sam do siebie. W tym mieście to jedyny sposób na przyzwoitą rozmowę.",
[2535371681]="Żadne stworzenie w lesie nie może umknąć Corandowi, tak wielka jest jego umiejętność śledzenia. Dobrze byś zrobił, słuchając jego nauk, jeśli chcesz odnieść choćby połowę jego sukcesów. Uwolnię cię od trudu śledzenia go i zaznaczę jego lokalizację na mapie, tam w Enklawzie Cenarion.",
[2535432443]="Nitki, które trzymają razem okropieństwa Stratholme, są bardzo poszukiwane przez rzemieślników: Niezwykle wytrzymałe - prawie niezniszczalne.",
[2536797299]="Przesuwaj te części w dół do statku!",
[2537637616]="SPALIĆ! Wy nędzniki! SPALIĆ!",
[2539158545]="%s wyrzuca odrażający Bile Slime!",
[2540598807]="Pokazaliśmy mu!",
[2540988639]="Nie wiesz, co robisz! Musimy cię zniszczyć dla twojego dobra.",
[2541504461]="Wszystko, czego mi teraz potrzeba, to złote lasso.",
[2542290946]="Sprawa załatwiona. Kieruję Mocą Kalimdoru. Upewnij się, że twoi żołnierze to rozumieją i przyjmują to za fakt. Rozlana krew jest już obfita. Niech jej nie będzie między naszymi frakcjami.",
