[2553842443]="Nasi nowi sojusznicy nas pomścią!",
[2554215043]="Armia nocnych elfów została wypchnięta przez Un'Goro, do granic pustyni Tanaris. Coś w Un'Goro uniemożliwiło Qiraji przejęcie ziemi. Nie do końca rozumiem to słowo, ale wierzę, że oznacza ono 'Ziemie Bogów'. Mówi się, że nie mogli 'wziąć Ziem Bogów'.",
