[2585415509]="Głupio szukałeś własnej zguby. Bezczelnie zlekceważyłeś moce przekraczające twoje pojmowanie. Walczyłeś zaciekle, aby wedrzeć się do królestwa żniwiarza. Teraz jest tylko jedna droga wyjścia - przejść samotną ścieżką potępionych.",
[2585966856]="Coś trzeba zrobić z plemieniem Blackwood.",
