[2586577717]="Interesuje mnie nauka krawiectwa.",
[2586875356]="Ragnaros? Straszne wiadomości...",
[2587334519]="Jeśli zamierzasz wejść w Głębiny Czarnej Skały, przyjdź do mnie porozmawiać. Mogę mieć dla ciebie pracę.",
