[2626512590]="Bitwa o Arathi Basin się rozpoczęła!",
[2626526093]="Być może masz to, co trzeba, być może nie. Jeśli tak, to wezmę cię na ucznia i nauczę cię tego, co chcesz wiedzieć. Jeśli nie... cóż, na tym poprzestanę.",
