[2635882809]="Umieść głowę Renda na pale.",
[2635952579]="Skłamałem...",
[2636744063]="Przepraszamy, że musimy opuścić klienta, ale mamy miejsca do odwiedzenia i ludzi do oszukania. Wrócimy tu gdzieś dziś później. Do widzenia!",
