[2656518521]="Ojej! Co to jest? Pomocy!",
[2657224937]="Więc dopóki tego nie zrobią... do widzenia!",
[2657598319]="Twoja śmierć nie pójdzie na marne, Taelan. Nowy Zakon rodzi się tego dnia... Zakon, który poświęci się wyeliminowaniu zła, które trapi ten świat. Zło, które nie może ukrywać się za polityką i uprzejmościami.",
