[2995519335]="Giń ty bezwartościowy!",
[2996518107]="Jestem magiem wielkiej mocy. Spędziłem swoje dni na badaniu umysłu i pamięci w odniesieniu do nauki i zapamiętywania wyuczonych zdolności. Nawet teraz doskonaliłbym swoje studia, gdyby nie wielkie głosy, które przyszły do mnie w nocy i oznajmiły, że moje usługi są potrzebne. Będę tu tylko przez krótki czas, oferując zdolność wymazania twoich talentów za darmo. Wkrótce znowu odejdę, a ty znów utkniesz z wyborami, jakich dokonasz.",
