[3004998407]="Nie zmuszaj mnie do brutalności.",
[3006616356]="Słodka ironia -- Siły Stormwindu zarznięte w obronie swojego miasta, aby teraz powstać i walczyć obok Bractwa jako narzędzia zniszczenia.",
[3006701921]="%s odchrząkuje.",
[3006787469]="Wracam teraz do miejsca, skąd przybyłem, aby znaleźć się tu ponownie i przeżyć tę samą epiczną tragedię.",
[3007348846]="Uważaj na każdy krok, żołnierzu. Stormpike zaścielili grunt wokół swoich baz minami. Porozmawiaj z naszym ekspertem od materiałów wybuchowych w wieży strażniczej na wschodzie, jeśli chcesz wiedzieć, jak rozbrajać ich pola minowe.",
[3007788907]="Wysiłki Hordy w zbieraniu są ukończone, . Teraz czekamy z dodatkowymi przygotowaniami, podczas gdy Przymierze kończy zbieranie do wojny.",
