[3009633317]="Co to na horyzoncie? Na pewno statek wroga! Ognia!",
[3010508809]="Niestety, obrona nocnych elfów była nie do utrzymania i Rajaxx wiedział, że nie będą mogli się bronić dużo dłużej. Ich wytrwałość powodowała jednak wielką frustrację u Rajaxxa i jeszcze większą frustrację u jego króla. Czekaj, królów? Niewiarygodne...",
[3011769568]="Mam właśnie zaklęcie, które otworzy te drzwi. Szkoda, że drzwi cel nie były zamknięte tak byle jak.",
[3011912549]="Moc Łzy Księżyców jest moja! Moja, mówię!",
[3012674707]="Choć żyję, aby służyć Matce Ziemi i Hordzie, nie mogę nie czuć się nieco zdenerwowany teraz, gdy zebraliśmy wszystko, czego potrzebujemy. Przynajmniej mamy trochę czasu, aż Przymierze skończy swoje wysiłki zbierania. Potem wszystko zostanie wysłane do Cenarion Hold w Silithus, a wojna prawdopodobnie nastąpi niedługo potem.",
[3013026085]="Czy mamy jeszcze daleko, ?",
[3013189494]="Jesteś inspiracją dla nas wszystkich, panie.",
[3014101886]="Teraz nasza kolej żeby ci się dostało!",
[3014359625]="Nic z ciebie nie będzie, Ribbly. Pora zapłacić za swoje zbrodnie!",
[3014399933]="Kto kontroluje Cmentarz Szronowego Wilka?",
[3014566603]="Czy ktoś proszę da mojemu małemu kociątkowi dobry dom?",
[3016208294]="Komak! Przysięgam, będę mieć pieniądze! Daj mi jeszcze trochę czasu!",
[3016344103]="Daj mi jeszcze jedną, Langston.",
[3016625567]="Jeszcze jedna minuta! Wytrzymaj, rytuał zaraz się uruchomi!",
[3017109029]="Śmiesz przelewać krew na terenie neutralnym? WYNOŚ SIĘ! WYNOŚ SIĘ STĄD!",
[3017309893]="Potrzebujemy więcej wilków! Chodź do stajni i pomóż nam!",
