[3028494421]="Niech cześć będzie , godny!",
[3028764393]="Jak śmiesz!",
[3029820856]="Sandfury panują!",
[3031361220]="Co to znowu, , nie mam całego dnia? Horda ukończyła swoje zbiory i teraz czeka tylko, aż Przymierze się zorganizuje i zrobi to samo. Może powinieneś szukać tam na zewnątrz kawałków Scepter of the Shifting Sands, aby uderzyć w gong na Estradzie Skarabeusza, otwierając bramy Ahn'Qiraju i tym samym rozpoczynając wojnę?",
[3031403976]="Tak, proszę przywołaj to z powrotem!",
[3032537918]="Zacznę czerpać energię z kamienia. Twoje zadanie, , to bronić mnie. To miejsce jest przeklęte...wierz mi.",
[3032858610]=" przebiegł szpaler! Trzykrotne hura dla !",
[3033086545]="Lysta, przyzwij... potwora!",
[3033094378]="Życie jest bez znaczenia. To w śmierci naprawdę jesteśmy poddawani próbie.",
[3033938523]="Porzuć swoje bitwy i sprawy, i przeglądaj moje niesamowite towary! Jestem w Darkshire tylko przez krótki czas... chwała Światłu za to.",
[3034721202]="Zwróć uwagę na wybredność diety zarażonego smoka. Wystarczy tylko przerażone mięso.",
[3035217649]="Wygląda na to, droga, że Przymierze zdołało zebrać wszystko, czego potrzeba do wysiłku wojennego. Teraz czekamy tylko na to, aby te biedne stworzenia Hordy skończyły ze swoim.",
[3037057182]="To moja droga albo Złota Droga. Zrozumiano?",
[3037291657]="Nie chowaliśmy tego dla ciebie, żebyś mógł to ukraść!",
