[3049700537]="Ile jeszcze dostaw potrzeba, aby wysłać natarcia lądowe?",
[3049905382]="Grumnus będzie twoim człowiekiem, . Nauczy cię sztuki płatnerza.",
[3052255191]="Najgorsze ma dopiero nadejść.",
[3052816057]="I nic nie wiem o tym ogniu...",
[3054601757]="Jasne, Paige. Bądź tylko delikatna.",
[3054640941]="Słabeusze Stormpike, stańcie przede mną w mojej twierdzy - jeśli się ośmielicie!",
