[3109087164]="Zły, . , zły!",
[3109907125]="Co to za moc płynie przeze mnie? Czy to moc szamanizmu, o której mówił Tor'gan...?",
[3110468721]="Ja... jestem... pokonany.",
[3110487667]="Kapitan Galvangar to zaufany pomocnik Drek'Thara. Prowadzi siły Hordy z Warowni Lodowej Krwi, w południowej części Pola Walki.\nKapitan Galvangar został zabity.",
[3110854810]="Witajcie, przyjaciele, w największym widowisku na Azeroth! Podejdźcie bliżej i zobaczcie wszystko, co mamy do zaoferowania. Skorzystajcie z karuzel i podziwiajcie widoki! Zachwycajcie się cudami, które Darkmoon Faire odkryło w tym ogromnym i tajemniczym świecie! Nie szczędziliśmy kosztów, by zapewnić wam rozrywkę, z której ucieszą się dzieci w każdym wieku!",
