[3125773226]="Straciłem Amulet Pana Valthalaka!",
[3127178278]="Te gobliny powinny się wstydzić! Bah!",
[3127854070]="World of Warcraft i Coca-Cola (R) połączyły siły, aby przynieść wam Promocję Letniej Coca-Coli World of Warcraft. Szukajcie kodów pod kapslami specjalnie oznaczonych butelek Coca-Coli. Potem wróćcie tutaj i wprowadźcie kod, aby wygrać wirtualny przedmiot.",
[3129544794]="%s jest osłabiony!",
[3129866733]="Będę musiał skoncentrować moje energie na tym nożu. Robiąc to, powinienem uchwycić kilka silniejszych wrażeń psychicznych z nim związanych.",
[3129954924]="%s zaczyna szaleńczo machać skrzydłami i głośno skrzeczeć. Masz wrażenie, że możesz być jego następnym posiłkiem.",
[3130397083]="Pod osłoną ciemności.",
[3130488127]="Chwała Mistrzowi!",
[3130806717]="Wstąp w szeregi! Walka u boku Legii Orgrimmar nie jest łatwa. Rekruci, których te elfy z Kręgu Cenariusa nam przysyłają, nigdy długo nie trwają.",
