[3136607574]="Eranikus jest tutaj! Szukajcie schronienia! Bezpieczeństwa!",
[3138034151]="Warownia Szronowego Skrzydła trzyma przejście między terytorium Przymierza a Polem Walki. Kontrolowana jest przez Hordę.",
[3138490773]="Miranda, czy mogłabyś mi powiedzieć, jaki jest koszt insygni dla przedmiotów, które oferujesz poszukiwaczom przygód z reputacją Exalted?",
[3140808268]="Daj mi żółwia do jazdy!",
[3141670469]="Potrzebujesz moich umiejętności alchemika, tak?",
