[3142209828]="Biegnij, dopóki możesz!",
[3142702524]="Zrujnowałeś swoje ziemie, nie zrujnujesz moich.",
[3144804834]="Jeztor żyje! Czas rozświetlić niebo Doliny, Dowódco.",
[3145238995]="Teraz poczujesz ból...",
[3145266136]="Wszystko, co robią, to trochę polowania i zbieractwa. Jaka w tym szkoda??",
