[3162091707]="Nie mogę uwierzyć, że tym chciwym goblinom pozwala się sprzedawać swoje towary, psując ducha tego sezonu.",
[3162742867]="Wyczuwam łotra.",
[3164329665]="Tylko cię spowolnię, ale żaden różowoskóry człowiek nie zatrzyma mnie przed wolnością!",
