[3165646170]="Harroc, weź pudełko narzędzi dla, .",
[3166263815]="Tak, tak, uspokój się, , nie ma się czym martwić. Na szczęście, kiedy po raz pierwszy dałeś mi lewą część, dostroiłem się do niej, więc sprowadzenie jej z powrotem z miejsca, gdzie ją 'zagubiłeś', wcale nie stanowi problemu.BProszę, i tym razem postaraj się lepiej o nią dbać.",
