[3167226209]="Edward, ty nas prowadzisz w złym kierunku. Wchodź tam.",
[3167890799]="Słyszałem, że są takie ogromne ryby, które potrafią chodzić po lądzie, żeby polować i jeść ludzi!",
[3167896402]="Bądź dumny z faktu, że Przymierze ukończyło wszystkie zadania zbierania postawione przed nim. Gotowe produkty są przechowywane i zabezpieczone, a nasi rzemieślnicy ciężko pracują nad przetwarzaniem surowców na materiały wojenne, które zostaną wysłane do Silithus, gdy tylko Horda skończy swoje zbieranie.",
[3167951002]="Nie teraz. Masz dla mnie jakieś zadania?",
[3169092784]="Musimy iść i spotkać się z innymi Uczniami. Jest wiele pracy do zrobienia, zanim będę mógł podjąć kolejną próbę przywrócenia Barrens. Żegnajcie, odważne dusze!",
[3170076008]="\"The Arcanist's Cookbook\" też zginęła! To katastrofa!",
