[3622500752]="To wszystko?",
[3623963917]="%s ryczy z podniecenia, gdy pędzi w kierunku Volcora. Kiedy dociera do swojego pana, Grimclaw liże mu twarz.",
[3625761762]="Panie, gdzie podziały się wszystkie drzewa?",
[3625763010]="%s rozpada się i traci siłę!",
[3627401892]="%s przekształca przedmioty w totem.",
[3629069532]="Najeźdźcy! Świetnie, zaczyna mi się nudzić...",
[3629764536]="%s celuje w butelki...",
[3630036809]="Bardzo dobrze, .",
[3630248801]="Kto kontroluje Bunkier Szronowego Skrzydła?",
[3630825074]="Tak jest, panie!",
[3631275938]="Nie okazujcie im miłosierdzia!",
[3631474090]="%s zaczyna oddawać każdy cios wymierzony w niego!",
[3632627235]="Zgubiłeś drogę?",
[3632928925]="Poddajcie się, a pozwolimy wam żyć, niewierni! Po prostu połóżcie broń i maszerujcie!",
[3633647129]="Chwała Elune! Nie wiem, czy przeżyłbym ten dzień bez ciebie, przyjacielu.",
[3633669759]="Masz rację. Umrzyj jak pies, którym jesteś.",
[3633810576]="Pamiętasz, Rajaxx, kiedy powiedziałem, że zabiję cię jako ostatniego?",
[3634960959]="Kwatermistrz Szronowego Wilka jest na południowy zachód od tego bunkra. Wejdź do bunkra, a następnie wyjdź w prawo, a zobaczysz kwatermistrza kawałek dalej ścieżką.",
[3636481273]="Ile czasu może zająć zebranie garści chwastów?",
[3636656372]="Żołnierze Stormpike, przyjdźcie mi z pomocą! Latarnia musi być umieszczona.",
[3639357520]="Kto się waży?! Zniszczę cię!",
[3640639025]="Padł.",
[3643176307]="Byłem poza domem przez długi czas... Lepiej wrócę.",
[3643234220]="Cmentarz Lodowatej Krwi znajduje się po południowej stronie Pola Walki, na wschód od Wieży Lodowatej Krwi.BPrzymierze aktualnie go kontroluje.",
[3643582167]="Nie! Nie możesz mnie pokonać!",
[3644003239]="Pierwsze zabójstwo jest moje! Ktoś chce się założyć?",
[3644878137]="Przepraszam, ale nie mogę sprzedawać koni żadnej osobie, która nie jest postrzegana przynajmniej jako przyjazna Królestwu Stormwind. Te wierzchowce to najlepsze, jakie znajdziesz gdziekolwiek, i na pewno nie chcemy ich w rękach naszych wrogów.BNie mówię, że ty jesteś wrogiem, oczywiście... po prostu zyskaj zaufanie Stormwind i wtedy możemy handlować.",
[3644930286]="Najlepsze piwo w Stormwind, Langston. Dzięki.",
[3645821045]="Aargh! Jesteś beznadziejny!",
[3647915858]="Bądź oczyszczony!",
[3648223724]="Daj mi fioletowy kostium ogra!",
[3648634074]="Noma powinna wkrótce mieć obiad gotowy. Mogę już pójść do środka.",
[3649110517]="Dzięki twojej pomocy mogę ocenić te tunele.",
[3650026248]="To powinno wystarczyć! Przynajmniej powinno!",
[3651619150]="Krasnoludy Ciemnego Żelaza odzyskają swoje prawowite ziemie!",
[3651908887]="Ludzie Hordy, obywatele Orgrimmar, podejdźcie i uczcijcie bohatera Hordy. W ten dzień, , pod patronatem naszego chwalebnego Wodza Wojennego, $g zadał : zadała; śmiertelny cios Czarnemu Stadu Smoków. Matka lęgu, Onyxia, została pokonana!",
[3652172065]="%s porzuca blok, który podtrzymywał w drzwiach, i patrzy na przynętę.",
[3652506333]="Chcesz broń, która będzie przedłużeniem twojej pięści? Tak, wierzę, że mogę ci coś pokazać.",
[3652871215]="Aaaarg!",
[3655124532]="Twój koniec nadchodzi!",
[3655193124]="Więzy ŻYCIA zostały przerwane! Marzyciele muszą być pomszczeni!",
[3655562923]="Dopiero co $g zacząłeś : zaczęłaś; poznawać moc Oka, . Jeśli chcesz wzmacniać zdolności Oka, to masz zadanie do wykonania.",
[3656115992]="Tam... to powinno pomóc. Teraz powiedz mi, co się stało, Grimclaw.",
[3657477622]="Czas na atak! Za Hordę!",
[3658467736]="...mięso... muszę się żywić!",
[3658527089]="Dorwijcie ich, moje piękności... i ich małe psiaczki też!",
[3658539305]="Powiedz mi o Kapitanie Galvangarze.",
[3659239056]="Posiłek przybył!",
[3661233730]="Czujesz moc, ??? Czas na ROCK!",
[3661686400]="Nawet demony potrafią się bać...",
[3663149994]="Arcykaplanka będzie ucztować na twoich kościach!",
[3663800819]="Pilnuj moich pleców, to może się źle skończyć.",
[3664737161]="Ściany komnaty się trzęsą. Coś się dzieje...",
[3664756059]="Ciesz się resztą pobytu w Menethil. Nie potrwa to już wiele dłużej.",
[3664839440]="Spójrz, tuż przy powierzchni wody!",
[3665024504]="Patrolujcie linię frontu, żołnierze!",
[3665090638]="Bitwa!  Czuję wasz strach, !",
[3665129736]="%s celuje...",
[3670065849]="Nieznane formy życia wykryte... analiza w toku...",
[3670272085]="%s jest usłany złamanymi kośćmi i okruchami krakersów.",
[3671887090]="Kel'Thuzad uczyni z Patchwerka swojego wcielenia wojny!",
[3673067815]="Twoja wiadomość do nas dotarła, Dowódco, ale nasze zaangażowanie tutaj w żaden sposób nie jest sankcjonowane przez Wielkiego Krzyżownika.",
[3673339605]="Twój zwierzak jest wspaniały, Gerardzie, ale myślę, że potrzebuje obroży z dzwoneczkiem.",
[3673666252]="Nasza sprawa pada na głuche uszy za grubymi, kamiennymi murami Stormwinda.",
[3673769061]="Głupce !  Nie jesteś w stanie zmierzyć się z moją mocą!",
[3674435145]="%s wpada w szał, widząc, jak jego raptor pada w walce!",
[3676105153]="Eranikus, Tyran Snu, został całkowicie pochłonięty przez Światło Elune. Spokój opanowuje Moonglade.",
[3676148642]="Kto waży się wkroczyć na tereny Blackrock Clan? Śmierć temu!",
[3677118397]="Ah, wolność! Choć krótka, tak słodka ona jest...",
[3677267626]="%s przywołuje Czarnorękiego Tkacza Grozy do pomocy!",
[3677928074]="Musimy się spieszyć.",
[3677963685]="Wreszcie... śmierć! Przeklęty bądź, Hakkar! Przeklęty!",
[3678261443]="Wewnętrzne bramy Ahn'Qiraj otwierają się z trzaskiem.",
[3678497653]="Wola %s słabnie.",
[3679191456]="Czy mogę ci pomóc coś znaleźć?",
[3679471671]="Kto tam idzie?",
[3681916293]="Teraz musimy czekać, . Niedługo Nagowie odkryją, co zrobiliśmy.",
[3682001543]="Duchy szepczą mi do ucha. Są niespokojne i pełne niepokoju.",
[3682251582]="Uciążliwe szczeniaki. Nauczę was nie mieszać się!",
[3682272891]="Tutaj zaczyna się coś ciekawego. Mój plan to podążać wzdłuż górskiej ściany, trzymając ją po naszej lewej stronie. W ten sposób nie zgubimy się w dżungli i zmniejszymy liczbę wrogów. Jesteś gotów?",
[3682669854]="Uważajcie! Uważajcie! W dziczy czai się zagrożenie! Night Watchers, bądźcie czujni!",
[3683575796]="Matko Ziemi, daj mi moc, aby naprawić to rozlanie krwi!",
[3684218795]="Tu się zaczyna!",
[3684405115]="|cffffff00Wieża Eastwall została przejęta przez Hordę!|r",
[3684664105]="NIE! Anaya... Anaya! Nie opuszczaj mnie! Proszę...",
[3684704377]="%s wznosi okrzyki!",
[3686057528]="Pomoc! Atakują!",
[3688095646]="Cześć Sovik, chciałbym obejrzeć twoje towary.",
[3688102395]="%s zostaje wciągnięty do skrzyni!",
[3689114220]="Tutaj. Weź skrzynię pojemników ochronnych i zaklęcie manifestacji. Będą ci potrzebne do twojej misji.",
[3689665890]="AAAAAAA! Dopadł mnie!",
[3689837376]="%s rozpoczyna odliczanie.",
[3690973692]="Tak jak powinno być...",
[3691995457]="Macie jakieś drobne?",
[3693037546]="Gdy nadejdzie pora, moja pani. Wszystko będzie jasne, gdy nadejdzie pora. Pan się już porusza. Spoglądaj na niebo, bo Potomstwo Nozdormu powróciło.",
[3693933111]="Zdaje się, że wcale nie jest to wyzwanie. Zobaczmy, jak poradzisz sobie z drugim testem. Lysta, przyprowadź sługusów Króla Lisza.",
[3694304575]="Widzę w twoich oczach, że znasz tragedię panującą w Stratholme. Jeśli chcesz położyć kres nędznemu bytowi nieszczęsnych dusz tam uwięzionych, wejdź do koła. Wiedzie ono wprost do bram płonącego miasta.",
[3694973993]="Broń Nighthaven, bohaterze...",
[3695666079]="HAKKAR ŻYJE!",
[3696073728]="Kapitan nie żyje.",
[3697295878]="Będzie twoją zagładą!",
[3698311417]="U twojego boku, pani!",
[3699066929]="Przeklęte duchy! Puśćcie przeszłość! Kryształ Zin-Malor już was nie wiąże!",
[3699587144]="Valstann Staghelm służył jako prawa ręka Fandrala. Dumny i szlachetny wojownik, jego poświęcenie i adoracja dla swojego ojca były niezachwiane... a Cesarze Bliźniacy wyczuli to jako słabość. Słabość, którą mogliby wykorzystać.",
[3700434590]="%s prycha.",
[3702074371]="Dobre miecze, solidne topory. Nie mam już nic, czego mógłbym cię nauczyć w wyrobie broni. Weź swoją dumę i odwagę przed Kelgrukiem Bloodaxe, a on wykuje je w umiejętności, których będziesz potrzebować.",
[3703533536]="%s ustrzelił bawoła!",
[3704651144]="%s patrzy z boku na bok...",
[3705178593]="Łagodny głos %s zanika w mgłach: \"Wiedz, że zawsze będę cię kochać...\"",
[3705345899]="Och, znów się zabłąkałem. Przepraszam.",
[3705487568]="Nie mamy czasu do stracenia. To będzie naprawdę długi bieg! Osłoń mnie!",
[3706295033]="Witaj, . Wyglądasz znajomo... czy już się kiedyś spotkaliśmy? Cóż, jeśli tak, to... z pewnością otrzymałeś tajny kod. Powiedz mi swój kod, a dam ci prezent!",
[3706587674]="Nie masz tu miejsca w tych ogrodach. Twoje ciało nakarmi nasze piękne stworzenia!",
[3706607957]="Ale to nie może być poprawne. Gdzie włożyłem tamtą drugą książkę?",
[3706763885]="Za Dragonmaw!",
[3706799859]="Pomocy!  Proszę, musicie mi pomóc!",
[3706881694]="%s rozwiewa się na twoich oczach.",
[3708866593]="Twoje wyzwanie się nie powiodło!",
[3710597390]="Bardzo dobrze. Jesteś zwolniony, szeregowcze. Odpoczywaj, ale nie czuj się zbyt komfortowo. Kurzen nie będzie nas zostawiać w spokoju na zawsze.",
[3710881171]="Zadziwiające!  Zatem indurium jest kluczem!",
[3712080244]="Kto ośmiela się zakłócić świętość Eldre'Thalas? Stawcie mi czoła, tchórze!",
[3712561857]="Będziesz godną ofiarą dla Ragnarosa.",
[3713932608]="Zapłacisz ostateczną cenę za tę bezczelność, mały robaku. Twoja dusza będzie moja!",
[3715697322]="Patrz! Tam przy ścianie tunelu!",
[3716252819]="%s schyla się, aby zbadać swój strzał.",
[3716611610]="Spraggle! Nie myślałem, że wrócę!",
[3716666295]="Jesteś ślepy, młody? Shayis stoi tuż na zewnątrz.",
[3717163741]="Opowiedz mi o Warowni Szronowego Wilku.",
[3717240972]="Twój los jest zapieczętowany, Mokvar! Zapłacisz za twoje czyny przeciwko Lordowi Valthalakowi!",
[3717267785]="Co się stało, Matko Ziemi? Dlaczego czar się nie powiódł?",
[3719608153]="Cześć. Bez urazy, ok?",
[3719693339]="Nie wywiązałem się z obowiązku strzegania Świątyni... moja skorumpowana dusza nie ma pokoju...",
[3719718287]="%s syczy.",
[3719897271]="%s zaczyna łączyć kryształy o różnych kolorach.",
[3723400931]="Tylko ciało i kości. Śmiertelnicy to tak łatwa zdobycz...",
[3723976701]="Grimclaw?! Spokojnie, przyjacielu... gdzie jest twój pan Volcor?",
[3724405827]="Spróbujmy tego...",
[3725912671]="Musisz zrobić to, co uważasz za słuszne, Marku. Służyliśmy razem pod wodzą Turaliona. On uczynił nas obu mężczyznami, którymi jesteśmy dzisiaj. Czy popełnił błąd ze mną? Naprawdę wierzysz, że moim zamiarem jest wyrządzić szkodę naszemu sojuszowi? Czy splamiłbym honor naszych bohaterów?",
[3729382769]="Pokażcie swoją odwagę, mężowie i kobiety Azeroth! Odeprzyjcie inwazję Qiraji!",
[3729830803]="Musi być w ostatniej celi. Chyba że... go zabili.",
[3730071461]="Techbot jest wrażliwy i te słowa ranią moje uszy. :[ Bądź dla mnie miły. Po prostu chcę pomagać.",
[3730705344]="Daj mi młode hipogryfa!",
[3732884675]="Obaj kapitanowie Hordy i Przymierza upadli! Pokonaj Drek'Thara, zanim będzie za późno!",
[3733318639]="Witaj! Wyglądasz znajomo... czy już się spotkaliśmy? Cóż, jeśli tak, to... z pewnością otrzymałeś tajny kod. Powiedz mi swój kod, a dam ci prezent!",
[3735784305]="Nie!!! Klątwa na was, intruzi! Armie Króla Lisza będą was tropić. Nie unikniecie swojego losu...",
[3736077996]="Bądź ostrożny. Te wilki lubią się chować wśród drzew.",
[3737374797]="Dobrze, już tutaj jestem. Chodź kupić moje towary, dopóki jest okazja. Daję ci pierwszą szansę na te rzeczy.",
[3738105526]="Następnym razem przyprowadź więcej przyjaciół!",
[3738435108]="Nie cofnie się przed niczym, by dotrzeć do fizycznej manifestacji Malfuriona. To nie może się stać... Musimy utrzymać bestię zajętą wystarczająco długo, aby Tyrande mogła przybyć.",
[3738671981]="Głowa do góry! Ból mija, a $gdziewczęta kochają mężczyzn z bliznami:mężczyźni kochają kobiety z bliznami;!",
[3738880286]="\"Umiejętność dla tych, którzy pragną pokonać przeszkody.\" Tak właśnie Faelyssa opisuje swój zestaw umiejętności. Jeśli wierzysz tak jak ona, to znajdź drogę do Enklawy Cenariańskiej w północnej części Darnassus, gdzie prowadzi swoje zajęcia.",
[3741286444]="%s wpada w szał, widząc śmierć szczeniaka!",
[3741468237]="Następnym razem gdy zobaczę któregokolwiek z was niepracującego, każę Buzzerowi uciąć mu głowę!",
[3741586650]="Oczyszczanie świata z nieczystego plugastwa to niełatwa praca, Nancy. Ktoś musi to robić.",
[3742038366]="Ale tak się nie miało stać. Gdy ich wrogowie się zbliżali, zbroja Anathery została przebita demonicznym, skażonym ostrzem. W szale bitwy nic nie mogło jej uratować.",
[3742082012]="I pozostań martwy!",
[3743505153]="UMRZYJCIE, ŚMIERTELNICY!",
[3743804905]="Walczcie do ostatniego oddechu, bracia i siostry!",
[3744976590]="Więcej agentów Syndykatu, mogę się założyć! Nigdy nie odbierzesz Alterac... ani Southshore!",
[3745357165]="Pyszne. Uwielbiam pieczonego Plainstridera.",
[3745414792]="Schronienie Szronowego Wilka zostało zajęte przez Przymierze!",
[3746074748]="Lysta, przywołaj jeńców.",
[3746401117]="%s zatrzymuje się i zaczyna uwalniać antidotum w powietrze.",
[3746949404]="Stańcie i walczcie!",
[3748072174]="Sądzę, że to ostatni z nich. Szczęście, że $g przyszedłeś : przyszłaś; dokładnie teraz... Nie byłem pewny, jak długo jeszcze mogę pozostać ukryty.",
[3748326543]="Gdybym mógł znaleźć \"Magic and the Ways of Power\". Ach, tutaj to jest, co tu robiła?",
[3749793791]="Czy tak bardzo chcesz umrzeć? Z przyjemnością ci w tym pomogę...",
[3750054160]="Wygląda na to, że będziecie potrzebować innej lekcji, śmiertelnicy!",
[3750512481]="Ok! Zacznijmy!",
[3751808323]="Nigdy nie miałem wielkiego użytku z łuku, ale te karabiny, które gobliny robią, są bardzo przydatne na polowaniu. Ale ciągle nie mogę się przyzwyczaić do zapachu.",
[3753377821]="Jestem BOT. Posiadam mnóstwo informacji. Aby dowiedzieć się, co wiem, szepnij do mnie.",
[3755864796]="Dalej przeglądasz pamiętnik, szukając informacji, które mogłyby pomóc w poszukiwaniach skradzionej skrzyni.BNa ostatnich stronach książki widzisz zapisaną czerwonym ołówkiem notatkę Jamesa na marginesie. Brzmi ona: \"Stary dom blisko Stone Cairn Lake... gnolle doskonale sprawdzą się jako ochroniarze.\"BNie ma powodu sądzić, że skrzynia jest właśnie tam, ale wygląda na to, że nie ma żadnych innych wskazówek.",
[3757105506]="Opcja bankiera",
[3757466544]="Przychodzisz się uczyć, mon?",
[3758019129]="Alexstrasza, daj mi siłę do odpędzenia naszych wrogów!",
[3759014957]="Czy już nikt nie PUKA???!",
[3759209542]="My, Przymierze, zwyciężymy!",
[3759716457]="Cień Plagi wciąż ciąży nad tą ziemią, głupcy! Nigdy nie zwyciężycie!",
[3760436678]="Pozdrowienia!",
[3760726156]="opcja taksówki",
[3762136047]="Chodźcie, moi akolici. Weźcie pręty kanałów i stwórzcie większy krąg przyzywania.",
[3762392740]="Możesz liczyć na mnie, Jeztor.",
[3762432259]="Zrobiliśmy to! Dziękuję jeszcze raz! Biegnę naprzód!",
[3762740092]="Moc! Wspaniała moc!",
[3762896566]="Ojej...",
[3763304683]="Uważaj się za szczęściarza, śmiertelniku. Przynajmniej twoje zwłoki są jeszcze jakoś przyzwoite.",
[3763963470]="Koniec jest blisko.",
[3766646280]="Tak, tak. Słyszałem wiele o tych nowych flarged. Pancerz został usunięty z obudowy, aby zmniejszyć wagę. Bargh! Nonsens!",
[3767346058]=" obronił południową farmę!",
[3767616289]="%s kiwa głową ze zrozumieniem.",
[3769772156]="Musisz być w grupie rajdowej, mieć co najmniej 50. poziom i Drakefire Amulet w ekwipunku, aby wejść.",
[3770306579]="Bunkier Północny Dun Baldaru jest atakowany! Jeśli go nie powstrzymamy, Przymierze go zniszczy!",
[3771452699]="Płyny i mieszanki bulgoczą i wpadają w spazmy, gdy się zbliżasz. Obok sprzętu leży duża para szczypiec, która wygląda na to, że byłaby odpowiednia do wrzucania próbek szlamu. Istnieje sprzęt ochronny, ale wydaje się być zakurzony i całkowicie ignorowany. Czy wkładasz swoje próbki do zlewek?",
[3771768823]="Ach... Moje eksperymenty nigdy mi się nie udają. Może powinienem wrócić w górę rzeki.",
[3771797644]="Kapitan Hordy Galvangar został zabity. Pokonajcie Drek'Thara i zwycięstwo będzie nasze!",
[3772272278]="Prawie skończyłem, . Jeszcze kilka drobnych poprawek!",
[3772619277]="Może mogę cię czegoś nauczyć...",
[3774658012]="Wreszcie moja dusza może spocząć... Och, najdroższy Cerellean...",
[3775685896]="Musisz być dostrojony i należeć do grupy rajdowej, aby wejść.",
[3776364784]="Torto, moja miłości! Wreszcie wróciłem.",
[3776898384]="%s stoi przed Mocą Kalimdoru.",
[3780723581]="%s rzuca dynamit przez powietrze i ląduje blisko.",
[3780894588]="Dziękuję za pomoc. Dzięki tobie kolejna przesyłka bezpiecznie dotarła do wykopalisk.",
