[3848827425]="Karczmy to miejsca, gdzie możesz odpocząć po swoich przygodach. Jeśli nie będziesz nocować w takiej karczmie, to nie będziesz w pełni odpoczęty, gdy znowu wyruszysz na pustkowie.BW każdej karczmie możesz również zdobyć kamień paleniska, a kiedy będziesz gotów odpocząć, możesz użyć tego kamienia paleniska, aby powrócić do karczmy, z której go otrzymałeś.",
