[3854716507]="Ryba jest doskonała, Jessica.",
[3854783544]="W tym świecie, gdzie czas jest twoim wrogiem, jest moim największym sojusznikiem. Ta wielka gra życia, w którą, jak ci się wydaje, grasz, w rzeczywistości gra tobą. A na to mówię...",
