[3889116977]="Trzeba czegoś więcej niż gawiedź, aby mnie powalić!",
[3889971949]="Brawa dla !",
[3890003842]="Valstann, chcąc zadowolić ojca, przekonał Fandrala do pozwolenia mu poprowadzenia małego batalionu w obronie Southwind. Oczywiście, wraz ze zwrotem pola bitwy na ich korzyść, nic złego nie mogło spotkać jego ukochanego dziecka. Pułapka przeszła niezauważona. Valstanna schwytali czający się Qiraji, a Southwind Village została doszczętnie zniszczona. Sam Rajaxx zabrał jeńca Valstanna na linię frontu, gdzie - w obecności Staghelma i nocnych elfów - brutalnie stracił młodego nocnego elfa.",
[3890900039]="%s pochłania wieżę wartowniczą. Wieża jest w płomieniach!",
[3891240458]="Hurra! Są w tym teraz!",
[3891421294]="I tak się zaczyna...",
